def main():
    changed = 0
    unchanged = 0
    for density, b64_data in ICON_B64.items():
        target_dir = os.path.join(RES_DIR, f"mipmap-{density}")
        target_path = os.path.join(target_dir, "ic_launcher_home_foreground.png")

        raw_bytes = base64.b64decode(b64_data)

        os.makedirs(target_dir, exist_ok=True)

        if os.path.exists(target_path):
            with open(target_path, "rb") as f:
                existing = f.read()
            if hashlib.sha256(existing).digest() == hashlib.sha256(raw_bytes).digest():
                print(f"[=] mipmap-{density}/ic_launcher_home_foreground.png já está atualizado, pulando.")
                unchanged += 1
                continue

        with open(target_path, "wb") as f:
            f.write(raw_bytes)
        print(f"[OK] mipmap-{density}/ic_launcher_home_foreground.png escrito ({len(raw_bytes)} bytes).")
        changed += 1

    print()
    print(f"Concluído: {changed} arquivo(s) atualizado(s), {unchanged} já estavam corretos.")
    print()
    print("Estrutura ic_launcher_home.xml (adaptive icon) já aponta corretamente")
    print("para @mipmap/ic_launcher_home_foreground em todas as densidades — nada")
    print("mais precisa mudar. Compile com:")
    print("    ./gradlew assembleNoQuickstepDebug")
    print()
    print("Depois de testar e confirmar, lembre de: git add -A && git commit && git push")

if __name__ == "__main__":
    main()
